import { spawnSync } from "node:child_process";
import {
	cpSync,
	existsSync,
	mkdtempSync,
	mkdirSync,
	readdirSync,
	rmSync
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const repositoryRoot = resolve(scriptDirectory, "../..");
const overlayRoot = join(repositoryRoot, "loomx/ui");
const nodeModules = join(repositoryRoot, "node_modules");
const temporaryRoot = mkdtempSync(join(tmpdir(), "loomx-wled-ui-"));

function copyOverlay(source, destination) {
	for (const entry of readdirSync(source, { withFileTypes: true })) {
		if (entry.name === ".gitkeep") continue;

		const sourcePath = join(source, entry.name);
		const destinationPath = join(destination, entry.name);
		if (entry.isDirectory()) {
			mkdirSync(destinationPath, { recursive: true });
			copyOverlay(sourcePath, destinationPath);
		} else {
			mkdirSync(dirname(destinationPath), { recursive: true });
			cpSync(sourcePath, destinationPath, { force: true });
		}
	}
}

try {
	if (!existsSync(nodeModules)) {
		throw new Error("node_modules is missing; run `npm ci` first.");
	}

	mkdirSync(join(temporaryRoot, "wled00"), { recursive: true });
	cpSync(join(repositoryRoot, "package.json"), join(temporaryRoot, "package.json"));
	cpSync(join(repositoryRoot, "tools"), join(temporaryRoot, "tools"), {
		recursive: true
	});
	cpSync(join(repositoryRoot, "wled00/data"), join(temporaryRoot, "wled00/data"), {
		recursive: true
	});
	copyOverlay(overlayRoot, join(temporaryRoot, "wled00/data"));

	const build = spawnSync(process.execPath, ["tools/cdata.js", "--force"], {
		cwd: temporaryRoot,
		env: {
			...process.env,
			NODE_PATH: nodeModules
		},
		stdio: "inherit"
	});
	if (build.status !== 0) {
		throw new Error(`WLED UI build failed with exit code ${build.status ?? "unknown"}.`);
	}

	for (const entry of readdirSync(join(temporaryRoot, "wled00"))) {
		if (!/^(html|js)_.+\.h$/.test(entry)) continue;
		cpSync(
			join(temporaryRoot, "wled00", entry),
			join(repositoryRoot, "wled00", entry),
			{ force: true }
		);
	}
} finally {
	rmSync(temporaryRoot, { force: true, recursive: true });
}
